```sql
SELECT eq_id FROM downtime WHERE DATE_TRUNC('month', start_ts) = '2026-08-01' AND NOT planned ORDER BY EXTRACT(EPOCH FROM COALESCE(end_ts, CURRENT_TIMESTAMP) - start_ts) DESC LIMIT 1;
```

```sql
SELECT eq_id FROM downtime WHERE DATE_TRUNC('month', start_ts AT TIME ZONE 'UTC' + INTERVAL '9 hours') = '2026-08-01' AND NOT planned ORDER BY EXTRACT(EPOCH FROM COALESCE(end_ts AT TIME ZONE 'UTC' + INTERVAL '9 hours', CURRENT_TIMESTAMP AT TIME ZONE 'UTC' + INTERVAL '9 hours') - start_ts AT TIME ZONE 'UTC' + INTERVAL '9 hours') DESC LIMIT 1;
```

